class Solution:
    def findMinimumTime(self, tasks: List[List[int]]) -> int:
        tasks.sort(key=lambda t: t[1])
        used = [False] * 2001
        ans = 0
        for s, e, d in tasks:
            need = d - sum(used[s:e + 1])
            t = e
            while need > 0:
                if not used[t]:
                    used[t] = True
                    ans += 1
                    need -= 1
                t -= 1
        return ans

