class Solution {
public:
    int findMinimumTime(vector<vector<int>>& tasks) {
        sort(tasks.begin(), tasks.end(), [](auto& a, auto& b){ return a[1] < b[1]; });
        array<bool, 2001> used{};
        int ans = 0;
        for (auto& t : tasks) {
            int need = t[2];
            for (int i = t[0]; i <= t[1]; i++) need -= used[i];
            for (int i = t[1]; need > 0; i--) {
                if (!used[i]) { used[i] = true; ans++; need--; }
            }
        }
        return ans;
    }
};

