class Solution {
public:
    int findMinimumTime(vector<vector<int>>& tasks) {
        sort(tasks.begin(), tasks.end(), [](auto& a, auto& b){ return a[1] < b[1]; });
        vector<int> used;
        int ans = 0;
        for (auto& t : tasks) {
            int need = t[2];
            need -= upper_bound(used.begin(), used.end(), t[1]) - lower_bound(used.begin(), used.end(), t[0]);
            for (int i = t[1]; need > 0; i--) {
                if (!binary_search(used.begin(), used.end(), i)) {
                    used.insert(upper_bound(used.begin(), used.end(), i), i);
                    ans++; need--;
                }
            }
        }
        return ans;
    }
};

