class Solution {
    public int findMinimumTime(int[][] tasks) {
        Arrays.sort(tasks, (a, b) -> a[1] - b[1]);
        TreeSet<Integer> used = new TreeSet<>();
        int ans = 0;
        for (int[] t : tasks) {
            int need = t[2] - used.subSet(t[0], true, t[1], true).size();
            for (int i = t[1]; need > 0; i--) {
                if (used.add(i)) { ans++; need--; }
            }
        }
        return ans;
    }
}

